import{_ as t,o as r,c as o,a2 as e}from"./chunks/framework.wVcpyw2-.js";const i="/images/placeholder-notification-pipeline.svg",g=JSON.parse('{"title":"通知与推送","description":"通知与推送：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/notification.md","filePath":"features/notification.md","lastUpdated":1785020677000}'),s={name:"features/notification.md"};function l(n,a,h,d,p,u){return r(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="通知与推送" tabindex="-1">通知与推送 <a class="header-anchor" href="#通知与推送" aria-label="Permalink to &quot;通知与推送&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将点赞、回复、订单等业务事件，通过站内通知、微信模板、短信、App 推送等渠道送达用户。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>通知模块已在授权中开通。</li><li>站内通知默认可用；微信模板需 <a href="/features/wechat">微信配置</a>；短信需 <a href="/features/sms">短信配置</a>。</li><li><strong>App 推送（iOS / Android）</strong> 须在 <strong>服务器环境变量</strong> 中配置，管理后台无对应 Tab。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="_1-事件模板" tabindex="-1">1. 事件模板 <a class="header-anchor" href="#_1-事件模板" aria-label="Permalink to &quot;1. 事件模板&quot;">​</a></h3><p>路径：<strong>通知控制台 → 事件模板</strong></p><p>为每种业务事件（如被回复、被点赞、订单状态变更）配置：</p><ul><li>通知标题与正文（支持变量占位，页面有说明）</li><li>启用哪些渠道：站内、Push、微信公众号、小程序订阅、短信等</li><li>优先级与失败是否尝试下一渠道</li></ul><p>新站部署后通常已有默认模板，上线前请逐条核对渠道是否符合预期。</p><h3 id="_2-微信模板" tabindex="-1">2. 微信模板 <a class="header-anchor" href="#_2-微信模板" aria-label="Permalink to &quot;2. 微信模板&quot;">​</a></h3><p>路径：<strong>通知控制台 → 微信模板</strong></p><p>将事件类型与微信公众平台 / 小程序后台申请的 <strong>模板 ID</strong> 对齐，并映射字段变量。</p><p>前置：</p><ul><li><strong>系统配置 → 微信小程序 / 微信公众号</strong> 已填 AppID、Secret</li><li>用户已关注公众号或已在小程序订阅相应消息</li></ul><h3 id="_3-系统广播-可选" tabindex="-1">3. 系统广播（可选） <a class="header-anchor" href="#_3-系统广播-可选" aria-label="Permalink to &quot;3. 系统广播（可选）&quot;">​</a></h3><p>路径：<strong>通知控制台 → 系统广播</strong></p><p>向指定区域或全站用户发送运营类站内通知。</p><h3 id="_4-通知记录与追踪" tabindex="-1">4. 通知记录与追踪 <a class="header-anchor" href="#_4-通知记录与追踪" aria-label="Permalink to &quot;4. 通知记录与追踪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>通知记录</strong></td><td>查看历史发送与状态</td></tr><tr><td><strong>消息链路追踪</strong></td><td>排查某条通知在各渠道的成功 / 失败</td></tr><tr><td><strong>通知编排</strong></td><td>高级编排规则（按需使用）</td></tr></tbody></table><h3 id="_5-对外机器人推送-可选" tabindex="-1">5. 对外机器人推送（可选） <a class="header-anchor" href="#_5-对外机器人推送-可选" aria-label="Permalink to &quot;5. 对外机器人推送（可选）&quot;">​</a></h3><p>若要把订单/笔记等事件推到企业微信、钉钉或自建脚本，请使用：</p><p><strong>通知控制台 → 机器人推送</strong></p><p>完整步骤见 <strong><a href="/features/open-stream">机器人推送（对外事件流）</a></strong>。<br> 注意：这与「用户体系 → 官方机器人」（站内助手）不是同一功能。</p><h3 id="_6-app-推送-fcm-apns" tabindex="-1">6. App 推送（FCM / APNs） <a class="header-anchor" href="#_6-app-推送-fcm-apns" aria-label="Permalink to &quot;6. App 推送（FCM / APNs）&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">不在后台配置</p><p>iOS（APNs）与 Android（FCM）的密钥、Bundle ID、Project ID 等须由 <strong>服务器运维</strong> 在部署环境变量中设置，例如 FCM 服务账号 JSON、APNs 的 <code>.p8</code> 密钥等。配置完成后，在 <strong>事件模板</strong> 的渠道中勾选 Push 即可。</p></div><p>管理员只需：确认运维已完成环境变量配置 → 模板渠道包含 <code>push</code> → 用户 App 已上报设备 Token。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>通知支持 <strong>按区域</strong> 设置静默时段、渠道开关等（在通知相关区域配置页或编排中，以实际菜单为准）。</p><p>优先级一般为：<strong>用户个人设置 → 区域配置 → 平台默认</strong>。</p><p>静默时段内，Push / 微信 / 短信可能延迟或跳过，站内通知通常仍写入。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>用测试账号触发一条业务（如 A 回复 B 的评论），B 在 <strong>消息 / 通知中心</strong> 收到站内通知。</li><li>若配置了微信模板：B 绑定微信且满足订阅条件时，收到微信服务通知。</li><li><strong>通知控制台 → 通知记录</strong> 中该条状态为成功；失败则看 <strong>消息链路追踪</strong> 原因。</li><li>Push：运维确认环境变量后，真机登录 App，触发事件后锁屏可见推送。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>只有站内通知，没有微信 / Push</strong></p><ul><li><strong>事件模板</strong> 中是否勾选对应渠道。</li><li><strong>微信模板</strong> 是否映射 template_id；用户是否订阅 / 关注。</li><li>Push 是否已由运维配置 FCM / APNs 环境变量。</li></ul><p><strong>夜间仍收到推送</strong></p><ul><li>检查区域 <strong>静默时段</strong> 与用户个人通知设置。</li></ul><p><strong>模板变量显示空白</strong></p><ul><li><strong>微信模板</strong> 字段映射是否与微信后台 keyword 一致。</li><li><strong>事件模板</strong> 变量名是否与系统预设一致（参考页面提示）。</li></ul><p><strong>大量发送失败</strong></p><ul><li><strong>系统监控 → 系统状态</strong> 查看 Redis、队列是否正常。</li><li>短信 / 微信配额是否用尽。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/wechat">微信（登录/支付）</a></li><li><a href="/features/sms">短信验证码</a></li><li><a href="/features/bot-notify">官方机器人</a></li></ul><p><img src="'+i+'" alt="通知投递示意"></p>',46)])])}const f=t(s,[["render",l]]);export{g as __pageData,f as default};
